-- AI 智能客服工作台 v3 增量迁移（幂等）：剔时表 timing_logs（5-6月真实脱敏数据）
CREATE TABLE IF NOT EXISTS timing_logs (
  id BIGSERIAL PRIMARY KEY,
  log_date DATE,           -- 日期
  person VARCHAR(40),       -- 客服姓名
  cat VARCHAR(60),          -- 工作项（货柜工单/BD客诉/售后退款效期质量等）
  qty NUMERIC(8,2),         -- 工作量（单数）
  hours NUMERIC(8,2),       -- 时长（小时）
  note VARCHAR(200),        -- 备注（质量预处理/SA升级/看视频等）
  created_at TIMESTAMPTZ DEFAULT now()
);
DO $$
BEGIN
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', 'timing_logs');
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'timing_logs' AND policyname = 'wb_all_timing_logs') THEN
    EXECUTE format('CREATE POLICY wb_all_%I ON %I FOR ALL USING (true) WITH CHECK (true)', 'timing_logs', 'timing_logs');
  END IF;
END $$;
DELETE FROM timing_logs;
SELECT setval(pg_get_serial_sequence('timing_logs', 'id'), COALESCE((SELECT MAX(id) FROM timing_logs), 1));
